const { withProjectBuildGradle } = require('expo/config-plugins');

// Notifee does not publish `app.notifee:core` to any public Maven repository —
// the AAR ships inside the npm package, at android/libs. Without this repo the
// Android build fails with "Could not find any matches for app.notifee:core:+".
//
// `android/` is generated by prebuild and gitignored, so this belongs in a
// config plugin rather than an edit to the generated Gradle file.
const REPO = `        maven { url "$rootDir/../node_modules/@notifee/react-native/android/libs" }`;

module.exports = function withNotifeeMaven(config) {
  return withProjectBuildGradle(config, (config) => {
    if (config.modResults.language !== 'groovy')
      throw new Error('with-notifee-maven only supports the Groovy build.gradle');

    if (config.modResults.contents.includes('@notifee/react-native/android/libs'))
      return config;

    // Into allprojects, which is what every module — including :notifee_react-native — resolves against.
    config.modResults.contents = config.modResults.contents.replace(
      /allprojects\s*\{\s*repositories\s*\{/,
      match => `${match}\n${REPO}`,
    );

    if (!config.modResults.contents.includes('@notifee/react-native/android/libs'))
      throw new Error('with-notifee-maven found no allprojects.repositories block to extend');

    return config;
  });
};
